mapper.delete:
DELETE ct
FROM content_tags ct
INNER JOIN contents c
ON c.id = ct.content_id
WHERE c.deleted_at IS NULL
AND (

    (
    c.type = #{content.type}
    AND c.external_source = #{content.externalSource}
    AND c.external_id = #{content.externalId}
    )

)

mapper.insert:
INSERT INTO content_tags (
content_id,
tag,
value
)


        SELECT
        c.id,
        #{tag.tag},
        #{tag.value}
        FROM contents c
        WHERE c.type = #{content.type}
        AND c.external_source = #{content.externalSource}
        AND c.external_id = #{content.externalId}
        AND c.deleted_at IS NULL

mapper.select:
SELECT c.id AS content_id, c.external_source, c.type, c.external_id, CASE WHEN c.deleted_at IS NULL THEN FALSE ELSE TRUE END AS deleted FROM contents c WHERE ( c.external_source, c.type, c.external_id ) IN (
( #{identifier.externalSource}, #{identifier.type}, #{identifier.externalId} )
)
